/* global self, URL */
// Displays what the server sends. The service worker is generated by
// Workbox and had no push handler: Apple delivered each notification to
// the phone and nothing showed it. iOS also revokes the subscription of
// a site that receives pushes without showing them.
self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { body: event.data ? event.data.text() : '' };
  }
  const options = {
    body: data.body || '',
    icon: 'icons/icon-192.png',
    badge: 'icons/favicon-64.png',
    // Where tapping it goes: the inbox sends '/?revisar=<id>' (BANDEJA.md).
    data: { url: data.url || '' },
  };
  // One tag per user for what arrives on its own: a burst replaces the
  // previous banner instead of stacking four ("4 por revisar").
  if (data.tag) {
    options.tag = data.tag;
    options.renotify = true;
  }
  event.waitUntil(self.registration.showNotification(data.title || 'Step up', options));
});

/**
 * The app lives under the service worker's scope (/step-up/ on GitHub
 * Pages), so '/?revisar=x' is read relative to it, not to the domain root.
 */
function targetUrl(url) {
  if (!url) return self.registration.scope;
  return new URL(String(url).replace(/^\//, ''), self.registration.scope).href;
}

// Tapping it opens the app on that entry, or brings the open one forward there.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = targetUrl(event.notification.data && event.notification.data.url);
  const deepLink = url !== self.registration.scope;
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windows) => {
      for (const w of windows) {
        if (!('focus' in w)) continue;
        if (deepLink && 'navigate' in w) return w.navigate(url).then((c) => (c || w).focus());
        return w.focus();
      }
      return self.clients.openWindow(url);
    }),
  );
});
